style.css:
@-moz-document domain("olx.pl"), domain("olx.ua"), domain("olx.ro"), domain("olx.pt"), domain("olx.bg"), domain("olx.kz") {
/* ============================================================
     OLX ships a Tailwind + design-token frontend. Most colors
     resolve from CSS custom properties on :root, so re-pointing
     those tokens flips the bulk of the UI. The remaining light
     surfaces are emotion (css-*) wrappers with literal hex values
     and hashed class names, so they are handled structurally from
     stable data-testid / id anchors.
     ============================================================ */

  :root {
    color-scheme: dark !important;

    /* ---- Surfaces ---- */
    --color-background-primary: #14181d !important;
    --colorsBackgroundPrimary: #14181d !important;
    --color-background-secondary: #1c2128 !important;
    --colorsBackgroundSecondary: #1c2128 !important;
    --color-background-elevated: #1c2128 !important;
    --colorsBackgroundElevated: #1c2128 !important;
    --color-background-inverse: #0d1117 !important;
    --colorsBackgroundInverse: #0d1117 !important;
    --color-background-disabled: #21262d !important;
    --colorsBackgroundDisabled: #21262d !important;
    --color-background-action-secondary: #21262d !important;
    --colorsBackgroundActionSecondary: #21262d !important;
    --color-background-transparent: #14181d00 !important;
    --colorsBackgroundTransparent: #14181d00 !important;

    /* ---- Foreground / text ---- */
    --color-foreground-primary: #e6edf3 !important;
    --colorsForegroundPrimary: #e6edf3 !important;
    --color-foreground-secondary: #9aa6b0 !important;
    --colorsForegroundSecondary: #9aa6b0 !important;
    --color-foreground-placeholder: #7d8893 !important;
    --color-foreground-on-dark: #e6edf3 !important;

    /* The "action" foreground (#02282c) is OLX's near-black. It paints the
       Nexus design-system components: rating-histogram counts, chip labels,
       secondary/tertiary button labels, and every `fill="currentColor"` icon
       (favourite hearts, dropdown check marks, location pins, chevrons). It
       is NOT one of the tokens the theme originally remapped, so all of those
       rendered dark-on-dark. Disabled/accent/status foregrounds ship dark or
       low-contrast values for the same reason. `on-accent` stays dark: it is
       the label colour on the mint accent fill. */
    --color-foreground-action-primary: #c4cdd6 !important;
    --colorsForegroundActionPrimary: #c4cdd6 !important;
    --color-foreground-accent: #5fd0c6 !important;
    --colorsForegroundAccent: #5fd0c6 !important;
    --color-foreground-disabled: #6b7681 !important;
    --colorsForegroundDisabled: #6b7681 !important;
    --colorsForegroundPlaceholder: #7d8893 !important;
    --color-foreground-status-success: #57ccc4 !important;
    --colorsForegroundStatusSuccess: #57ccc4 !important;
    --color-foreground-status-warning: #d6a425 !important;
    --colorsForegroundStatusWarning: #d6a425 !important;
    --color-foreground-status-error: #f0795f !important;
    --colorsForegroundStatusError: #f0795f !important;

    /* ---- Borders ---- */
    --color-border-subtle: #2d333b !important;
    --colorsBorderSubtle: #2d333b !important;
    --color-border-primary: #2d333b !important;
    --colorsBorderPrimary: #2d333b !important;
    --color-border-strong: #454d57 !important;
    --colorsBorderStrong: #454d57 !important;
    --color-border-medium: #2d333b !important;
    --colorsBorderMedium: #2d333b !important;
    --color-border-focus: #1fcabf !important;
    --colorsBorderFocus: #1fcabf !important;
    --color-border-disabled: #2d333b !important;
    --colorsBorderDisabled: #2d333b !important;
    --color-border-status-error: #c2402b !important;
    --colorsBorderStatusError: #c2402b !important;

    /* ---- OLX accent (raw #23E5DB mint) refined for dark ----
       Keep the recognizable OLX teal/mint identity but pull the
       saturation/lightness down a touch so it sits calmly on the
       near-black palette and dark text on it stays readable. */
    --color-background-accent: #1fcabf !important;
    --colorsBackgroundAccent: #1fcabf !important;
    --color-border-accent: #1fcabf !important;
    --color-background-accent-subtle: #103c3b !important;
    --colorsBackgroundAccentSubtle: #103c3b !important;

    /* ---- Status colors: keep semantic hue, settle onto dark ---- */
    --color-background-status-success: #1f6b54 !important;
    --colorsBackgroundStatusSuccess: #1f6b54 !important;
    --color-background-status-success-subtle: #102a23 !important;
    --colorsBackgroundStatusSuccessSubtle: #102a23 !important;
    --color-background-status-error: #c2402b !important;
    --colorsBackgroundStatusError: #c2402b !important;
    --color-background-status-error-subtle: #3a1b16 !important;
    --colorsBackgroundStatusErrorSubtle: #3a1b16 !important;
    --color-background-status-warning: #d6a425 !important;
    --colorsBackgroundStatusWarning: #d6a425 !important;
    --color-background-status-warning-subtle: #322a12 !important;
    --colorsBackgroundStatusWarningSubtle: #322a12 !important;
  }

  /* ---- Base page ---- */
  html, body {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }

  /* `domain("olx.pl")` also matches every OLX subdomain, including the help
     centre at pomoc.olx.<tld> — a Salesforce Lightning community this theme
     does not cover. The base paint above turned its body dark while its own
     near-black article headings and paragraphs kept their light-page colours,
     so every help article rendered dark-on-dark. Salesforce roots every
     community page at <html class="slds-no-wcag">, which nothing on the OLX
     marketplace carries: hand that surface back rather than half-theme it. */
  html.slds-no-wcag,
  html.slds-no-wcag body {
    background-color: #ffffff !important;
    color: #181818 !important;
  }
  html.slds-no-wcag a:hover { color: #014486 !important; }

  /* ---- Soften every default light border into a dark hairline ---- */
  * { border-color: #2d333b !important; }

  /* OLX's icons are inline <svg>s whose paths are fill="currentColor", and the
     colour is set ON THE SVG by a per-deploy hashed emotion class holding the
     literal near-black #02282c — not by a design token and not by the icon's
     container. So every one of them (dropdown check marks, chevrons, the
     geolocation pin, the sort/list-view toggles, the category caret) rendered
     dark-on-dark even though its surrounding text was correctly light. Let the
     icon inherit the colour of the thing it belongs to; icons with explicit
     path fills (brand logos, country flags, illustrations, rating stars) are
     untouched because an explicit fill wins over currentColor. */
  #mainContent svg,
  #footerContent svg { color: inherit !important; }
  /* …except the rating stars, whose gold IS the artwork: they are currentColor
     glyphs too, so plain inheritance would grey them out. */
  #mainContent svg[data-testid="star-filled"],
  #mainContent svg[data-testid="star-half"] { color: #ffce32 !important; }

  /* Selected-tab underline. OLX draws it as an INSET box-shadow in the literal
     near-black #02282c (not a border, not a token), so on dark it disappears
     and the active tab is indistinguishable from the inactive ones. The search
     filters (Wszystkie / Firmowe / Prywatne) and the seller-profile tabs
     (Wszystkie ogłoszenia / Oceny) mark the selected tab with
     data-is-active="true"; login.olx.<tld> instead uses a roving tabindex where
     the SELECTED tab is the one carrying tabindex="-1". (aria-selected is NOT a
     tab hook here — the sort dropdown puts it on its options, which must stay
     underline-free.) Repaint the underline in the OLX accent and brighten the
     active label. */
  button[data-is-active="true"],
  [data-testid="tabs"] button[tabindex="-1"] {
    box-shadow: inset 0 -3px 0 0 #1fcabf !important;
  }
  button[data-is-active="true"],
  button[data-is-active="true"] span,
  [data-testid="tabs"] button[tabindex="-1"],
  [data-testid="tabs"] button[tabindex="-1"] span {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }

  /* Skip-navigation links ("Przejdź do głównej części / stopki") live at the
     top of the #hydrate-root shell and slide into view on keyboard focus. The
     link text carries the near-black #02282c -webkit-text-fill token, so it
     renders dark-on-dark and is unreadable when focused; the wrapping first-div
     container also ships a literal white background. Both skip hrefs are stable
     and there is exactly one skip-nav ListContainer (scoped to that first div so
     other ListContainers aren't touched): give the box an opaque dark surface
     and lift the link text to legible light, forcing -webkit-text-fill-color. */
  #hydrate-root > div:first-of-type,
  #hydrate-root > div:first-of-type [data-nx-name="ListContainer"] {
    background-color: #1c2128 !important;
  }
  #hydrate-root a[href="#mainContent"],
  #hydrate-root a[href="#footerContent"] {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }

  /* ============================================================
     Header / global nav (OLX dark-teal bar -> deep neutral dark)
     ============================================================ */
  header.app-header,
  header[class*="app-header"] {
    background-color: #0d1117 !important;
    border-bottom: 1px solid #2d333b !important;
  }
  header.app-header a,
  header[class*="app-header"] a,
  header.app-header button { color: #e6edf3 !important; }

  /* The "post new ad" CTA reads as a white pill by default. Its inner
     <span> carries its own near-black -webkit-text-fill-color, so set
     BOTH on the wrapper and the span or the label stays invisible. */
  [data-testid="post-new-ad-button"],
  [data-cy="post-new-ad-button"] {
    background-color: #1fcabf !important;
    color: #07232a !important;
    -webkit-text-fill-color: #07232a !important;
    border-color: #1fcabf !important;
  }
  [data-testid="post-new-ad-button"] span,
  [data-cy="post-new-ad-button"] span {
    color: #07232a !important;
    -webkit-text-fill-color: #07232a !important;
  }

  /* Notification + account dropdowns */
  [data-testid="notification-hub-dropdown"],
  [data-cy="notification-hub-wrapper"],
  [class*="menu-dropdown"],
  [role="menu"], [role="listbox"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #e6edf3 !important;
  }

  /* ============================================================
     Main page wrappers — flatten literal light backgrounds.

     OLX's content lives inside emotion (css-<hash>) shells whose
     class names change every deploy, so we never target those
     hashes. Instead we anchor on the STABLE page-shell ids
     (#hydrate-root / #mainContent / #footerContent /
     #searchmain-container) and neutralise EVERY descendant
     div/section/article/ul to transparent — that wipes the literal
     #F2F4F5 / #FFFFFF content bands regardless of how deep the
     hashed wrapper sits. The real cards then re-establish their own
     opaque dark surface below (data-testid anchored). The <img>
     element itself is left alone (its pixels aren't a CSS bg). */
  #hydrate-root,
  #mainContent,
  #footerContent,
  #searchmain-container,
  [data-testid="home-page"],
  [data-testid="listing-grid"],
  [data-testid="listing"],
  main, .listing-grid {
    background-color: #14181d !important;
  }
  /* Blanket light-shell neutraliser: anything structural under the
     stable page containers loses its hardcoded light background and
     shows the dark base. Cards re-opaque themselves afterwards. */
  #mainContent div, #mainContent section, #mainContent article, #mainContent ul,
  #footerContent div, #footerContent section,
  #searchmain-container div, #searchmain-container section, #searchmain-container article {
    background-color: transparent !important;
  }
  [data-testid="home-page"] div,
  [data-testid="home-page"] section,
  [data-testid="listing-grid"] > div {
    background-color: transparent !important;
  }
  /* The homepage/search "content sheet" #searchmain-container carries an
     INLINE `background:#F2F4F5 !important` (set so the page sits opaque over
     a takeover/skin wallpaper ad). Inline !important can't be beaten by any
     stylesheet rule, so the container itself stays light — and the blanket
     neutraliser turns its children transparent, letting that light band show
     through the entire category grid + promoted-listings area (headings and
     tile labels go light-on-light). Its DIRECT children have no inline style,
     so re-opaque them to the dark base here; anchored under #mainContent to
     out-specify the neutraliser. The real search field / promo tiles / cards
     re-establish their own elevated surface on top. */
  #mainContent #searchmain-container > div {
    background-color: #14181d !important;
  }

  /* ============================================================
     Floating surfaces — RE-OPAQUE over the neutraliser.

     The blanket `#mainContent div/section/article/ul {transparent}`
     rule above (specificity id+type, 0,1,1) also blanks the
     background off every interactive floating panel that lives
     inside #mainContent — the global search autocomplete, the
     filter flyouts (sort / category / price-range / multiselect)
     and any role=menu/listbox popover. Left alone they render fully
     SEE-THROUGH, so the listing grid + breadcrumbs scroll right
     through the open menu and it's unreadable. Re-establish a solid
     opaque dark surface on each, anchored on the STABLE flyout/menu
     testids + roles and scoped under #mainContent so the rule
     out-specifies the neutraliser (0,2,0 > 0,1,1). */
  #mainContent [data-testid="flyout-content"],
  #mainContent [data-testid="category-dropdown-list"],
  #mainContent [data-testid="search-autosuggession"],
  #mainContent [data-testid="search-autosuggession"] [role="listbox"],
  #mainContent [role="menu"],
  #mainContent [role="listbox"],
  #mainContent [class*="multi-select-body"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #e6edf3 !important;
  }

  /* ============================================================
     Search bar (white field on the hero) -> dark input
     ============================================================ */
  [data-testid="search-form"],
  [data-testid="search-autosuggession"],
  form[data-testid="search-form"] > div {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  [data-testid="search-input"],
  [data-cy="search-bar-input"],
  [data-testid="location-search-input"],
  [data-cy="location-search-input"],
  input[type="text"], input[type="search"], input[type="number"],
  input[type="email"], input[type="password"], input[type="tel"],
  textarea, select {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  ::placeholder { color: #7d8893 !important; opacity: 1 !important; }

  /* Nexus checkboxes ("tylko ze zdjęciem", "Tylko z przesyłką", the sign-up
     consents). The real <input> is visually replaced by a sibling
     .n-checkbox-icon-wrapper <div>, which draws the box: a 2px #02282c outline
     when unchecked, and the SAME near-black as a solid fill (plus a white tick)
     when checked. Two of our own rules gutted it — the blanket border reset
     dropped the outline to the #2d333b hairline (1.4:1 on the page base, below
     the 3:1 needed for a control boundary), and the structural
     `#mainContent div { background: transparent }` neutraliser wiped the checked
     fill, so checked and unchecked differ only by a faint tick. Restore a
     legible outline and give the checked state the OLX accent fill. */
  .n-checkbox-icon-wrapper { border-color: #6b7681 !important; }
  input[aria-checked="true"] + .n-checkbox-icon-wrapper,
  #mainContent input[aria-checked="true"] + .n-checkbox-icon-wrapper {
    background-color: #1fcabf !important;
    border-color: #1fcabf !important;
  }
  input[aria-checked="true"] + .n-checkbox-icon-wrapper svg,
  #mainContent input[aria-checked="true"] + .n-checkbox-icon-wrapper svg {
    color: #07232a !important;
  }
  [data-testid="search-submit"] {
    background-color: #1fcabf !important;
    color: #07232a !important;
    border-color: #1fcabf !important;
  }
  /* Autosuggest / location dropdown panels */
  [data-testid="search-autosuggession"] [role="listbox"],
  [data-testid="suggestions"], .suggestions,
  [class*="autosuggest"] ul, [class*="dropdown"] ul {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* ============================================================
     Category quick-menu (homepage tiles)
     ============================================================ */
  [data-testid="home-categories-menu"],
  [data-cy="home-categories-menu"],
  [data-testid="home-categories-menu-row"],
  [data-testid^="cat-"], [data-cy^="cat-"] {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }
  /* Category tile LABEL is a <p> inside a[data-testid="cat-N"] carrying
     its own near-black -webkit-text-fill-color — set both so it reads. */
  [data-testid="home-categories-menu"] p,
  [data-testid^="cat-"] p, [data-cy^="cat-"] p,
  [data-testid^="cat-"] span, [data-cy^="cat-"] span {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }
  [data-testid="home-page"] [data-testid^="cat-promo-"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* Homepage content headings/text (e.g. the "OLX dla biznesu"
     business-promo band) ship near-black #14181d that vanishes once
     the band is flattened to dark. Remap content text under the
     home-page container, forcing -webkit-text-fill-color too. */
  [data-testid="home-page"] h1,
  [data-testid="home-page"] h2,
  [data-testid="home-page"] h3,
  [data-testid="home-page"] h4 {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  [data-testid="home-page"] p {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }
  /* SEO link lists at the bottom of the homepage ("Kategorie główne:"
     and "Popularne wyszukiwania:") are <a> elements carrying the
     near-black #02282c -webkit-text-fill token — they render fully
     dark-on-dark. Lift the home-page link text (and its inner span)
     to a legible muted grey; the category tiles inherit the same and
     stay readable. Brand CTAs live in the header, not here. */
  [data-testid="home-page"] a,
  [data-testid="home-page"] a span {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }
  [data-testid="home-page"] a:hover,
  [data-testid="home-page"] a:hover span {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }

  /* The homepage "site information" block (big OLX wordmark, SEO blurb and the
     "Dołącz do nas" Facebook / Instagram / TikTok / YouTube / LinkedIn /
     Pinterest row) draws its glyphs with fill="currentColor" over the literal
     near-black #02282c, so both the wordmark and five of the six social icons
     rendered invisible on the dark base. The Pinterest mark carries no fill at
     all and falls back to SVG's default black — force currentColor on the
     paths so it follows the link colour like its siblings. All six marks are
     monochrome, so nothing brand-coloured is flattened here. */
  #mainContent [data-testid="site-information"] > svg,
  #mainContent [data-testid="site-information"] a svg {
    color: #9aa6b0 !important;
  }
  #mainContent [data-testid="site-information"] a svg path,
  #mainContent [data-testid="site-information"] a svg g {
    fill: currentColor !important;
  }
  #mainContent [data-testid="site-information"] a:hover svg {
    color: #e6edf3 !important;
  }

  /* ============================================================
     Listing / ad cards
     The blanket neutraliser above (#mainContent div) out-specifies a
     bare [data-testid="l-card"], so the card re-opaque rules are
     anchored under the stable page container ids to win the cascade.
     ============================================================ */
  #mainContent [data-testid="l-card"],
  #searchmain-container [data-testid="l-card"],
  #mainContent [data-cy="l-card"] {
    background-color: #1c2128 !important;
    border: 1px solid #2d333b !important;
    border-radius: 8px !important;
  }
  /* Image placeholder block inside cards (grey #ECEEEF). OLX's card link now
     holds TWO `a > div` children: the FIRST is the photo container (holds the
     <img>), the SECOND is an absolutely-positioned overlay (favourite heart /
     badges) laid ON TOP of the photo. Painting a bare `a > div` opaque #21262d
     covered every loaded photo with the overlay. Scope the dark placeholder to
     the FIRST child only — it shows through as a dark box on image-less cards
     while the overlay stays transparent so loaded photos are visible. */
  #mainContent [data-testid="l-card"] a > div:first-child,
  #searchmain-container [data-testid="l-card"] a > div:first-child,
  #mainContent [data-testid="l-card"] figure {
    background-color: #21262d !important;
  }
  /* Card title is an <h4> inside [data-testid="ad-card-title"] with its
     own near-black -webkit-text-fill-color — set both on title + child. */
  [data-testid="ad-card-title"],
  [data-cy="ad-card-title"],
  [data-testid="ad-card-title"] a,
  [data-cy="ad-card-title"] a,
  [data-testid="ad-card-title"] h4,
  [data-testid="ad-card-title"] h3 {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  [data-testid="ad-price"] {
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
    font-weight: 700 !important;
  }
  [data-testid="location-date"] {
    color: #8b949e !important;
    -webkit-text-fill-color: #8b949e !important;
  }
  /* Search results count line ("Znaleźliśmy ponad 1000 ogłoszeń") */
  #mainContent [data-testid="listing-count-msg"],
  #mainContent [data-testid="listing-count-msg"] *,
  #mainContent [data-testid="total-count"],
  #mainContent [data-testid="total-count"] * {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }
  /* Promoted "z Pakietem Ochronnym" price badge text */
  [data-testid="btr-label-wrapper"],
  [data-testid="btr-label-wrapper"] *,
  [data-testid="btr-label-text"] {
    color: #6fe3da !important;
    -webkit-text-fill-color: #6fe3da !important;
  }

  /* Delivery / promoted / negotiable badges */
  [data-testid="card-delivery-badge"],
  [data-testid="btr-label-wrapper"],
  [data-testid="free-delivery-tag"] {
    background-color: #103c3b !important;
    border-color: #1fcabf !important;
  }
  /* free-delivery-tag ships a light mint (#C8F8F6) fill + dark teal
     text — flip the fill to the dark accent-subtle and lift the text. */
  [data-testid="free-delivery-tag"],
  [data-testid="free-delivery-tag"] * {
    color: #6fe3da !important;
    -webkit-text-fill-color: #6fe3da !important;
  }
  /* The delivery pills sit under #mainContent / #searchmain-container, where the
     blanket neutraliser (`#mainContent div`, 1,0,1) out-specifies the bare
     [data-testid] fill above (0,1,0) and strips it to transparent — so on the
     listing the badge lost its dark-accent pill and rendered as naked mint text
     floating on the card photo (contrast then depends on the user's photo).
     Re-assert the pill scoped under the page containers so it wins the cascade. */
  #mainContent [data-testid="free-delivery-tag"],
  #mainContent [data-testid="card-delivery-badge"],
  #searchmain-container [data-testid="free-delivery-tag"],
  #searchmain-container [data-testid="card-delivery-badge"] {
    background-color: #103c3b !important;
    border-color: #1fcabf !important;
  }

  /* "Wyróżnione" (Featured/highlighted-ad) badge sits over the dark card
     thumbnail carrying its own near-black #02282c -webkit-text-fill token, so
     it renders dark-on-dark and vanishes. It's the only card label using the
     stable data-nx-name="Tag" component wrapper (delivery/promoted badges have
     their own testids), so anchor there and lift it to the mint accent to keep
     the "featured" highlight identity legible on the dark thumbnail. */
  #mainContent [data-testid="l-card"] [data-nx-name="Tag"],
  #mainContent [data-testid="l-card"] [data-nx-name="Tag"] *,
  #searchmain-container [data-testid="l-card"] [data-nx-name="Tag"],
  #searchmain-container [data-testid="l-card"] [data-nx-name="Tag"] * {
    color: #6fe3da !important;
    -webkit-text-fill-color: #6fe3da !important;
  }

  /* The homepage "recommended"/partner (Storia real-estate) l-card variant
     adds a secondary parameter line — area / rooms, e.g. "352 m²" — inside an
     un-testid'd <span> carrying the dim #406367 token, so it renders low
     contrast on the dark card. Lift every card param <span> to a legible muted
     grey. The price is a <p> and the title an <h4> (not spans), so they stay
     untouched; the mint promoted/delivery badges and the white price are
     re-asserted just below so this broader span rule can't grey them out. */
  #mainContent [data-testid="l-card"] span,
  #searchmain-container [data-testid="l-card"] span {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }
  /* Services ads (and the whole seller-profile listing) hang "specialisation"
     chips under the title — "Elewacje i tynkowanie", "+3 więcej", … Each chip
     is a nested <span> with a literal `background:#FFFFFF` and a 1px #D8DFE0
     outline: a white pill on a white card, i.e. really just an outline chip.
     The blanket neutraliser only reaches div/section/article/ul, so the white
     survived while the param-lift above dimmed the label to #9aa6b0 — 1.6:1,
     unreadable. Drop the fill and let the (already softened) outline carry the
     pill; `transparent` is a no-op on every other span, and the card's delivery
     / promoted / "Wyróżnione" badges are <div>s, so none of them are flattened. */
  #mainContent [data-testid="l-card"] span > span,
  #searchmain-container [data-testid="l-card"] span > span {
    background-color: transparent !important;
  }
  /* Re-assert semantic card colours the param-lift above would otherwise flatten */
  #mainContent [data-testid="l-card"] [data-testid="ad-price"],
  #mainContent [data-testid="l-card"] [data-testid="ad-price"] span,
  #searchmain-container [data-testid="l-card"] [data-testid="ad-price"],
  #searchmain-container [data-testid="l-card"] [data-testid="ad-price"] span {
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
  }
  #mainContent [data-testid="l-card"] [data-testid="btr-label-wrapper"] span,
  #mainContent [data-testid="l-card"] [data-testid="btr-label-text"],
  #mainContent [data-testid="l-card"] [data-testid="free-delivery-tag"] span,
  #searchmain-container [data-testid="l-card"] [data-testid="btr-label-wrapper"] span,
  #searchmain-container [data-testid="l-card"] [data-testid="free-delivery-tag"] span {
    color: #6fe3da !important;
    -webkit-text-fill-color: #6fe3da !important;
  }

  /* Favourite (heart) toggle. The heart is an inline <svg> whose <path> is
     fill="currentColor", and OLX sets the colour on the SVG itself through a
     hashed emotion class carrying a literal #02282c — so colouring the wrapping
     <button> (which the theme already did) never reached the artwork and the
     heart rendered near-black on the dark card. Colour the SVG directly. */
  [data-testid="adAddToFavorites"],
  [data-testid="adAddToFavorites"] svg,
  [data-testid="observe-ad"] svg { color: #c4cdd6 !important; }

  /* Native "SPONSOROWANE" ads (OLX baxter native template) render inside the
     listing grid as plain HTML carrying their own near-black #02282c
     -webkit-text-fill token, so once the grid goes dark the ad title,
     advertiser line and the "i" attribution popup all fall dark-on-dark.
     Anchor on the stable #baxter-native-listing* id (the -olx-<tld>- segment
     varies per country) and lift the text; brighten the headline; flatten the
     small light info chip + the white attribution popup so it reads too. */
  [id^="baxter-native-listing"],
  [id^="baxter-native-listing"] * {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }
  [id^="baxter-native-listing"] [class*="title"] {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  /* These surfaces sit inside #mainContent, so the blanket neutraliser
     (`#mainContent div`, specificity 1,0,1) out-specifies a bare
     [id^=…] [class*=…] (0,2,0) and the background never landed: the ad's
     "Informacja o tej reklamie" popup rendered fully SEE-THROUGH over the
     creative, and the mint "SPONSOROWANE" disclosure band lost its tint
     entirely. Anchor under #mainContent (1,2,0) so they actually paint.
     The popup's downward caret is a real-element CSS triangle whose left/right
     borders must stay transparent — the blanket `* { border-color }` reset
     painted all four sides, so it rendered as a solid grey rectangle. */
  #mainContent [id^="baxter-native-listing"] [class*="_spnu"],
  #mainContent [id^="baxter-native-listing"] [class*="attribution"],
  #mainContent [id^="baxter-native-listing"] [class*="popup"],
  #mainContent [id^="baxter-native-listing"] [class*="tooltip"] {
    background-color: #103c3b !important;
    border-color: #2d333b !important;
  }
  #mainContent [id^="baxter-native-listing"] [class*="attribution-link"] {
    background-color: #1c2128 !important;
    border-color: #83a4ec !important;
  }
  #mainContent [id^="baxter-native-listing"] [class*="template__after"] {
    border-top-color: #83a4ec !important;
    border-right-color: transparent !important;
    border-left-color: transparent !important;
  }

  /* OLX's ad server pins a "ZAMKNIJ X" close button over each sticky/expandable
     slot with an INLINE `background: white` (not !important). Its label has no
     colour of its own, so it inherits the body text colour — which we flipped
     to light — and the only control that dismisses the ad became white-on-white.
     Give it the elevated dark surface it now needs. */
  .baxter-inner-sticky-close-button {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
    box-shadow: none !important;
  }

  /* Offer pages also inject an in-page ING loan-calculator native ad
     (#inter-box_ad-detail inside a qa-advert-slot) rendered as plain HTML.
     Its legal disclaimer ("RRSO … ING Bank Śląski S.A.") and the "Zobacz
     koszty kredytu" link carry a literal near-black colour, so once the box
     flattens to the dark base they render dark-on-dark and vanish. Lift its
     dark subtitle/footer text to a legible muted grey; the white headline,
     the grey slider labels and the accent "Oblicz ratę" button keep their
     own colour. Force -webkit-text-fill-color too (OLX drives text fill). */
  #inter-box_ad-detail .inter-box_subtitle_middle,
  #inter-box_ad-detail .inter-box_subtitle_bottom,
  #inter-box_ad-detail .inter-box_subtitle_middle *,
  #inter-box_ad-detail .inter-box_subtitle_bottom * {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }
  /* Its amount / term fields are `input[type="number"]` on a literal #eeeeee,
     and the "zł" / "msc" unit suffix is a white .inter-box_spec pill. The
     theme's generic input rule only listed text/search inputs, so the amount
     inherited the light text colour and read light-on-light. */
  #inter-box_ad-detail input[type="number"],
  #inter-box_ad-detail .inter-box_spec {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  /* ING brands the calculator in its orange: an #FF6200 "Oblicz ratę" CTA and
     #F2A066 field outlines. The CTA is a `button[type="submit"]`, so the OLX
     accent rule further down repainted an advertiser's brand button OLX teal,
     and the blanket border reset erased the field outlines. Give them back. */
  #inter-box_ad-detail .calculator_button_cta {
    background-color: #ff6200 !important;
    border-color: #ff6200 !important;
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
  }
  #inter-box_ad-detail input[type="number"] { border-color: #f2a066 !important; }
  #inter-box_ad-detail .inter-box_spec { border-color: #2d333b !important; }

  /* OLX's SSR ad slots (e.g. #baxter-top on the offer/listing pages) ship a
     full-width house-ad placeholder ("OLX REKLAMA") baked onto a WHITE canvas
     as a background-IMAGE, so the unfilled slot renders as a glaring white
     banner on dark. Because the white is a raster background-image (not a
     bg-color, and not a light gradient stop) BOTH the element-bg scan and the
     light-gradient scan miss it. Strip the placeholder image and drop the slot
     onto the dark base — a real ad loading into the slot lives in its own child
     iframe, so it is unaffected. Two class conventions ship these placeholders:
     `*-baxter-ssr-placeholder`/`with-placeholder-image` (e.g. #baxter-top on the
     offer/listing) and `baxter-placeholder--*` (e.g. #baxter-seller-billboard on
     the profile) — cover both. */
  [class*="ssr-placeholder"],
  [class*="baxter-placeholder"],
  [class*="with-placeholder-image"] {
    background-image: none !important;
    background-color: #14181d !important;
  }

  /* ============================================================
     Top promo / info banner strip (was pale yellow #FFF6D9)
     ============================================================ */
  #banner, #banner > div,
  #mainContent [data-testid="top-banner-wrapper"],
  #mainContent [data-testid="cta-banner-click"] {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  #mainContent [data-testid="banner-btn"],
  #mainContent [data-testid="bep-button"] {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* ============================================================
     Search-results page: filters sidebar, sort dropdowns, pills
     ============================================================ */
  /* The current OLX frontend nests the whole search/category page
     (filters + listing grid) under #mainContent — the old
     #searchmain-container id no longer exists, so these are anchored
     on #mainContent (and the stable filter/listing testids) which is
     where they actually live now. */
  #mainContent [data-testid="listing-filters"],
  #mainContent [data-testid="filters-container"],
  #mainContent [data-testid="qsearch-container"],
  #mainContent [data-testid="listing-filters-form"],
  #mainContent [class*="filter"] [role="button"],
  #mainContent [data-testid="chips-container"] > * {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #e6edf3 !important;
  }
  [data-testid="pagination-wrapper"] a,
  [data-testid="pagination-list"] li {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }
  [data-testid="pagination-forward"],
  [data-testid="pagination-back"] { color: #e6edf3 !important; }

  /* Search-results heading (h1[data-testid="heading"], "Sprzedaż
     elektroniki") + filter/sort labels + filter values all carry the
     near-black #02282c / dim #406367 content colour. Remap them under
     the listing-filters form / sorting wrapper and force
     -webkit-text-fill-color so the override wins. */
  #mainContent [data-testid="heading"],
  #mainContent [data-testid="listing-filters-form"] h1,
  #mainContent [data-testid="listing-filters-form"] h2,
  #mainContent [data-testid="listing-filters-form"] h3 {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  #mainContent [data-testid="listing-filters-form"] p,
  #mainContent [data-testid="listing-filters-form"] label,
  #mainContent [data-testid="listing-filters"] p,
  #mainContent [data-testid="listing-filters"] span,
  #mainContent [data-testid^="category-filter"] p,
  #mainContent [data-testid^="category-filter"] span,
  #mainContent [data-testid="filter-clear-all"],
  #mainContent [data-testid="filter-clear-all"] span,
  #mainContent [data-testid="sorting-wrapper"],
  #mainContent [data-testid="sorting-wrapper"] span {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }
  /* Filter segmented-control values (Wszystkie / Firmowe / Prywatne)
     are <span> inside <button> in a filter <header> — flip to legible. */
  #mainContent [data-testid="listing-filters"] button span,
  #mainContent [data-testid="listing-filters-form"] button span {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }
  /* "Zapisz" save-search CTA: accent fill, dark legible label */
  #mainContent [data-testid="save-search-button"],
  #mainContent [data-testid="save-search-form-submit"],
  #mainContent [data-testid="l-save-search-banner-button"] {
    background-color: #1fcabf !important;
    border-color: #1fcabf !important;
  }
  #mainContent [data-testid="save-search-button"],
  #mainContent [data-testid="save-search-button"] span,
  #mainContent [data-testid="save-search-form-submit"],
  #mainContent [data-testid="save-search-form-submit"] span,
  #mainContent [data-testid="l-save-search-banner-button"],
  #mainContent [data-testid="l-save-search-banner-button"] span {
    color: #07232a !important;
    -webkit-text-fill-color: #07232a !important;
  }

  /* Footer SEO sub-category link list (Fotografia / Komputery / … )
     at the bottom of search/category pages ships dim #406367 link text
     via its own -webkit-text-fill-color — lift it to a legible muted
     grey. These links live in <ul><li><a> blocks under #mainContent. */
  #mainContent ul li a,
  #mainContent ul li a span {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }
  #mainContent ul li a:hover,
  #mainContent ul li a:hover span {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }

  /* ============================================================
     Seller / user profile page (/oferty/uzytkownik/)

     A distinct #mainContent layout whose profile-header follow/share
     buttons, the "Wszystkie ogłoszenia / Oceny" tab bar, the filter &
     sort section labels, the result-count line, the seller metadata
     and the card location lines all ship the near-black #02282c / dim
     #406367 content tokens through -webkit-text-fill-color, so they
     render dark-on-dark. The offer/search remaps are anchored on
     testids this page doesn't use — cover its stable anchors here.
     ============================================================ */
  /* Profile tab bar — inactive tabs only; the active one keeps the brighter
     label + accent underline set in the tab block near the top of the file. */
  #mainContent button[data-is-active="false"],
  #mainContent button[data-is-active="false"] span {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }
  /* (The profile-header Obserwuj / Podziel się buttons used to need a
     parent-match rule here. They are Nexus secondary/tertiary buttons whose
     label reads the foreground-action-primary token, so the token remap at the
     top of the file now covers them — the .org.css build drops no rule.) */

  /* Filter/sort section labels (Kategorie / Sortuj / Znajdź na tej
     stronie) — lift, then re-assert the card title/price the broad
     seller-listing rule would otherwise flatten. */
  #mainContent [data-testid="seller-listing"] h4,
  #mainContent [data-testid="seller-listing"] > header,
  #mainContent [data-testid="seller-listing"] > header * {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }
  #mainContent [data-testid="seller-listing"] [data-testid="ad-card-title"],
  #mainContent [data-testid="seller-listing"] [data-testid="ad-card-title"] h4 {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  /* Result count + seller metadata (member-since / last-online) + card
     location lines (bare <p>, no location-date testid on this variant) */
  #mainContent [data-testid="results-counter"],
  #mainContent [data-testid="results-counter"] *,
  #mainContent [data-testid="lastSeenBox"],
  #mainContent [data-testid="lastSeenBox"] *,
  #mainContent [data-testid="l-card"] p {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }
  #mainContent [data-testid="seller-listing"] [data-testid="ad-price"],
  #mainContent [data-testid="seller-listing"] [data-testid="ad-price"] * {
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
  }

  /* ============================================================
     Individual offer / item page

     The offer content column is a stack of hashed emotion shells
     under #mainContent → div[data-testid="main"]; the blanket
     neutraliser above already flattens those literal light bands.
     Here we (a) RE-ESTABLISH opaque dark on the real floating cards
     (out-specifying the neutraliser via #mainContent), and (b) remap
     the near-black content text. OLX drives rendered text through
     -webkit-text-fill-color, so a `color`-only override silently
     fails — every text rule sets BOTH color and -webkit-text-fill.
     ============================================================ */
  /* Distinct cards within the offer page -> elevated surface */
  #mainContent [data-testid="ad-action-box"],
  #mainContent [data-testid="seller_card"],
  #mainContent [data-testid="map-aside-section"],
  #mainContent [data-testid="legal-information-accordion"],
  #mainContent [data-testid="user-profile-link"],
  #mainContent [data-testid="qa-skeleton-item"],
  #mainContent [data-testid="ad-card-loader"],
  #mainContent [data-testid="ad-login-dialog"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  /* In-content seller-contact card (white box under main > section) */
  #mainContent [data-testid="main"] > section > div {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* ---- Offer content text (was near-black #02282c on dark) ----
     The offer TITLE is an un-testid'd <h4>, and headings/labels/
     parameter rows/desc all inherit the same near-black; remap the
     whole content column's text and force -webkit-text-fill-color
     so the override actually wins. Brand-coloured controls (accent
     CTAs, the red "Zgłoś" report button) keep their own colour via
     the more specific rules that follow. */
  #mainContent [data-testid="main"] h1,
  #mainContent [data-testid="main"] h2,
  #mainContent [data-testid="main"] h3,
  #mainContent [data-testid="main"] h4,
  #mainContent [data-cy="ad_title"], #mainContent [data-testid="offer_title"] {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  #mainContent [data-testid="main"] p,
  #mainContent [data-testid="main"] li,
  #mainContent [data-testid="ad_description"],
  #mainContent [data-testid="ad_description"] *,
  #mainContent [data-testid="ad-parameters-container"] p,
  #mainContent [data-testid="ad-parameters-container"] li,
  #mainContent [data-testid="ad-parameters-container"] span,
  #mainContent [data-testid="trader-title"],
  #mainContent [data-testid="ad-posted-at"] {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }
  /* Seller-card metadata (member-since / last-online, was #406367) */
  #mainContent [data-testid="user-profile-user-name"],
  #mainContent [data-testid="member-since"],
  #mainContent [data-testid="user-profile-link"] p,
  #mainContent [data-testid="user-profile-link"] span,
  #mainContent [data-testid="ad-footer-bar-section"] span {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }
  /* Login prompt + its sign-in/register CTA (was #02282c dark-on-dark) */
  #mainContent [data-testid="prompt-message"] {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }
  /* Price */
  #mainContent [data-testid="ad-price-container"],
  #mainContent [data-testid="prices-wrapper"] {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  #mainContent [data-testid="prices-wrapper"] h3,
  #mainContent [data-testid="price-label"],
  #mainContent [data-testid="ad-price-value"] {
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
  }
  /* Promote / refresh action links (Promuj / Odśwież, were #02282c) */
  #mainContent [data-testid="ad-promotion-actions"] a,
  #mainContent [data-testid="ad-promotion-actions"] span,
  #mainContent [data-testid="to-back"],
  #mainContent [data-testid="to-back"] span {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }
  /* Keep the brand-red "Zgłoś" report button readable as itself */
  #mainContent [data-testid="ad-report-button"],
  #mainContent [data-testid="ad-report-button"] span {
    color: #f0795f !important;
    -webkit-text-fill-color: #f0795f !important;
  }
  /* Contact / chat / phone buttons + the login-dialog CTA -> accent
     fill with dark legible text (set BOTH color + text-fill). */
  /* The bottom "SKONTAKTUJ SIĘ" block repeats the message CTA under a different
     hook — [data-testid="chat-button"] — and paints it with OLX's near-black
     #02282c "inverse" fill instead of the accent. On white that reads as the
     primary button; on our #1c2128 card it is a 1.3:1 slab with no visible
     edge, sitting right next to the mint "Pokaż". Give it the same accent fill
     as its twin in the right rail so the two contact CTAs match. */
  /* The "Kup" safe-deal buy button ([data-testid="go-to-delivery-options"]) is
     OLX's near-black #02282c primary — the STRONGEST CTA on the light site. On
     our #1c2128 card that near-black sits at ~1.1:1, so the most important action
     on the page rendered as a near-invisible slab that reads as disabled next to
     the vivid teal message/call CTAs. It isn't in the accent group below, so give
     it the same accent fill as the other purchase CTAs. */
  #mainContent [data-testid="ad-contact-message-button"],
  #mainContent [data-testid="ad-contact-phone"],
  #mainContent [data-testid="show-phone"],
  #mainContent [data-testid="chat-button"],
  #mainContent [data-testid="go-to-delivery-options"],
  #mainContent [data-testid="phones-container"] button,
  #mainContent [data-testid="login-button"],
  #mainContent button[data-testid*="contact"] {
    background-color: #1fcabf !important;
    color: #07232a !important;
    border-color: #1fcabf !important;
  }
  #mainContent [data-testid="login-button"] span,
  #mainContent [data-testid="ad-contact-message-button"] span,
  #mainContent [data-testid="chat-button"] span,
  #mainContent [data-testid="go-to-delivery-options"] span,
  #mainContent [data-testid="phones-container"] button span {
    color: #07232a !important;
    -webkit-text-fill-color: #07232a !important;
  }
  /* The phone glyph beside "Pokaż" is an <svg> that IS the mint disc (the
     accent is its own background-color) with a fill="currentColor" handset.
     The blanket `#mainContent svg { color: inherit }` handed it the light body
     colour, so the handset washed out to 1.5:1 on its own accent fill. It is
     dark-on-mint natively; restore that and settle the disc on our accent. */
  #mainContent [data-testid="phones-container"] svg {
    background-color: #1fcabf !important;
    color: #07232a !important;
  }

  /* OLX serves logged-out offer pages with a full-bleed "skin"/wallpaper
     takeover ad (a position:absolute iframe sitting BEHIND the content
     column). On the light site the offer column is opaque white so the
     wallpaper only shows in the gutters; our blanket neutraliser made
     the offer column [data-testid="main"] transparent, so the teal ad
     bleeds straight THROUGH the description, chips and meta text and
     guts their contrast. Re-establish a solid dark backdrop on the
     content column (the gallery / cards keep their own surfaces on
     top). */
  #mainContent [data-testid="main"] {
    background-color: #14181d !important;
  }
  /* The offer page's RIGHT rail ([data-testid="aside"]) needs the same
     treatment: the neutraliser strips its light background, so the wallpaper
     takeover ad shows straight through the gaps between its cards. Two of its
     cards are white natively but have no testid of their own — the price/action
     card (first child) and the Zwroty / Pakiet Ochronny block (the sibling
     right after the location card) — so re-elevate them structurally. */
  #mainContent [data-testid="aside"] {
    background-color: #14181d !important;
  }
  #mainContent [data-testid="aside"] > div:first-child,
  #mainContent [data-testid="map-aside-section"] + div {
    background-color: #1c2128 !important;
  }
  /* Same takeover-ad bleed, one level further down the offer page: the two
     recommendation carousels ("Więcej od tego ogłoszeniodawcy" / "Zobacz też")
     paint their own #F2F4F5 band natively (the seller one via an INLINE style
     on its wrapper), and the neutraliser stripped both — so the full-bleed
     wallpaper ad showed straight through the band, behind the section heading
     and in every gap between cards. Both live inside a position:relative
     wrapper that paints after the ad slot, so an opaque background on the
     section itself is enough. */
  #mainContent [data-cy="seller-other-ads"],
  #mainContent [data-testid="ad-recommendations"] {
    background-color: #14181d !important;
  }
  /* …and the page-background bands BETWEEN those blocks. OLX writes them as an
     inline `background:#F2F4F5` on hashed wrappers — the 16px channel between
     the offer column and the right rail, and the 24-32px gaps between sections.
     An inline declaration without !important loses to the neutraliser, so those
     strips went transparent and the wallpaper ad striped the whole page. Match
     them on the serialized inline value (stable: the CSSOM always writes
     `rgb(242, 244, 245)`); the one band that also carries !important is
     #searchmain-container, whose children we re-opaque separately. */
  #mainContent div[style*="background: rgb(242, 244, 245)"] {
    background-color: #14181d !important;
  }
  /* Swiper draws the carousel arrows as ::after glyphs (content:"prev"/"next"
     in its icon font) that inherit the element's colour — OLX sets the literal
     near-black #02282c there, not a token, so both arrows rendered at 1.1:1 on
     the dark band. `*` cannot reach a pseudo-element; colour the button. The
     photo lightbox uses its own arrows and is outside #mainContent. */
  #mainContent .swiper-button-prev,
  #mainContent .swiper-button-next {
    color: #c4cdd6 !important;
  }
  /* "Zobacz wszystkie" (see all of this seller's ads) is a bare <a> in the
     carousel header carrying the same near-black fill token. */
  #mainContent [data-cy="seller-other-ads"] h3 + a {
    color: #5fd0c6 !important;
    -webkit-text-fill-color: #5fd0c6 !important;
  }

  /* Image gallery surrounds (out-specify the blanket neutraliser) */
  #mainContent [data-testid="image-galery-container"],
  #mainContent [data-testid="ad-photo"],
  #mainContent [data-testid="gallery"],
  #mainContent [data-testid="swiper-list"] {
    background-color: #0d1117 !important;
  }

  /* Full-screen photo lightbox. It renders into a `.n-modal-portal` OUTSIDE
     #mainContent, so none of the offer-page text rules reach it. Its dialog is
     the design system's INVERSE surface, and it colours the ad title with the
     `--color-background-primary` token — white on the light site, which we had
     to remap to the page base #14181d. So opening the lightbox printed the
     title in #14181d on a #0d1117 panel: the headline vanished completely, and
     the "Dodane <date>" line under it dropped to 1.9:1. Repaint both directly;
     the token itself must keep pointing at the page base. */
  .n-modal-portal [role="dialog"] [data-testid="offer_title"],
  .n-modal-portal [role="dialog"] [data-testid="offer_title"] h4 {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  .n-modal-portal [role="dialog"] [data-testid="ad-posted-at"] {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }
  /* The lightbox also duplicates the offer's login-nudge + contact CTAs, but every
     offer-page contact rule is #mainContent-scoped and this dialog lives in the
     .n-modal-portal OUTSIDE #mainContent. So inside the lightbox the login card
     kept its native OLX blue (#1d3c81) and the "Wyślij wiadomość" button its native
     grey secondary fill — both glare on the dark lightbox. Mirror the offer
     treatment for the portal so it matches the main page. */
  .n-modal-portal [data-testid="ad-login-dialog"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  /* Its prompt copy carries the near-black #14181d fill (designed for the light
     card), so once the card goes dark it drops to ~1:1 — lift it like the offer
     page does for #mainContent [data-testid="prompt-message"]. */
  .n-modal-portal [data-testid="prompt-message"] {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }
  .n-modal-portal [data-testid="ad-contact-message-button"],
  .n-modal-portal [data-testid="chat-button"] {
    background-color: #1fcabf !important;
    color: #07232a !important;
    border-color: #1fcabf !important;
  }
  .n-modal-portal [data-testid="ad-contact-message-button"] span,
  .n-modal-portal [data-testid="chat-button"] span {
    color: #07232a !important;
    -webkit-text-fill-color: #07232a !important;
  }

  /* ============================================================
     Login / registration pages (login.olx.<tld> — separate app,
     no design tokens, classic ids: #username / #password / .login-box)
     ============================================================ */
  [data-testid="core-layout"] {
    background-color: #14181d !important;
  }
  /* login.olx.<tld> renders a full-bleed OLX-blue brand splash BEHIND the
     sign-in card: a hashed wrapper with a literal `background:#3A77FF` plus
     lighter concentric ::before / ::after rings. That bright full-viewport
     blue fights the dark theme. The card (.login-box) re-opaques on top one
     level deeper, so flatten just that decorative wrapper (core-layout's
     3rd-level shell) and neutralise its ring pseudos to the dark base. Scoped
     to the login-only core-layout testid, so no other page is affected. */
  [data-testid="core-layout"] > div > div > div {
    background-color: #14181d !important;
  }
  [data-testid="core-layout"] > div > div > div::before,
  [data-testid="core-layout"] > div > div > div::after {
    background-color: transparent !important;
    background-image: none !important;
    box-shadow: none !important;
    border-color: transparent !important;
  }
  .login-box,
  [data-testid="login-form"],
  [data-testid="registration-form"],
  [data-testid="register-form"] {
    background-color: #1c2128 !important;
    border: 1px solid #2d333b !important;
    color: #e6edf3 !important;
  }
  /* Social sign-in buttons (white pills) -> elevated dark.
     The testid sits on a wrapper; the white surface is the inner button. */
  [data-testid="facebook-button"], [data-testid="facebook-button"] *,
  [data-testid="apple-button"], [data-testid="apple-button"] *,
  [data-testid="google-button"], [data-testid="google-button"] * {
    background-color: #21262d !important;
    border-color: #2d333b !important;
  }
  [data-testid="facebook-button"], [data-testid="apple-button"],
  [data-testid="google-button"] { color: #e6edf3 !important; }
  /* The Apple wordmark is a monochrome black SVG (hardcoded #000 / #002F34
     path fills), so it disappears once its pill goes dark. Facebook and Google
     keep their multi-colour marks. */
  [data-testid="apple-button"] svg path { fill: #e6edf3 !important; }
  /* Email + password fields */
  #username, #password,
  [data-testid="login-form"] input,
  [data-testid="register-form"] input {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  /* Tabs (Sign in / Register). The redesigned login app renders the two
     tab <button>s on a literal WHITE pill bar; flip the bar + buttons to
     the elevated dark surface and lift the labels (driven by the same
     near-black -webkit-text-fill token) so the active/inactive tab read. */
  [data-testid="tabs"] { color: #c4cdd6 !important; }
  [data-testid="tabs"] header,
  [data-testid="tabs"] button {
    background-color: #1c2128 !important;
  }
  [data-testid="tabs"] button,
  [data-testid="tabs"] button span {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }
  /* Email / password floating labels + the "lub" separator carry the
     near-black token and vanish on dark — force both colour channels.
     The redesigned sign-up form's stable testid is "register-form" (not
     "registration-form"), and its E-mail / Hasło floating labels + the
     consent-checkbox label <span>s render dark-on-dark unless covered, so
     anchor on BOTH testids and reach label spans too. */
  [data-testid="login-form"] label,
  [data-testid="login-form"] label span,
  [data-testid="registration-form"] label,
  [data-testid="registration-form"] label span,
  [data-testid="register-form"] label,
  [data-testid="register-form"] label span {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }
  /* Sign-up password checklist. Each unmet rule ("9 lub więcej znaków", …) is
     an <svg data-testid="false-icon"> whose disc is a literal `fill="white"`
     <rect> with a grey dash across it — invisible on the white card, so only
     the dash reads. On the dark card the disc becomes a row of glaring white
     dots. Sink the disc into the card surface; the dash stays. (The met state
     is a currentColor tick and needs nothing.) */
  svg[data-testid="false-icon"] rect[fill="white"] { fill: #1c2128 !important; }

  /* Show-password eye. The login app is a separate bundle that hardcodes the
     old #406367 secondary colour on the icon instead of reading the token. */
  [data-testid="toggle-password"],
  [data-testid="toggle-password"] svg { color: #9aa6b0 !important; }
  [data-testid="or-separator"],
  [data-testid="or-separator"] span {
    color: #8b949e !important;
    -webkit-text-fill-color: #8b949e !important;
  }
  /* Submit button keeps the OLX accent */
  [data-testid="login-submit-button"],
  [data-testid="register-submit-button"],
  button[type="submit"] {
    background-color: #1fcabf !important;
    color: #07232a !important;
    border-color: #1fcabf !important;
  }
  /* "Nie pamiętasz hasła?" (forgot-password) + the show-password eye are
     un-testid'd <button>s inside the login form carrying the near-black
     token — lift them. The accent submit button is re-asserted just below
     so it keeps its dark-on-teal label. */
  [data-testid="login-form"] button,
  [data-testid="login-form"] button span {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }
  [data-testid="login-form"] [data-testid="login-submit-button"],
  [data-testid="login-form"] [data-testid="login-submit-button"] span {
    color: #07232a !important;
    -webkit-text-fill-color: #07232a !important;
  }
  /* Footer legal blurb under the form (the "Kontynuując…" paragraph) is a
     near-black <p>; lift it while the Regulamin link keeps the teal below. */
  [data-testid="core-layout"] p,
  [data-testid="core-layout"] p span {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }
  [data-testid="terms-conditions-link"],
  a[href*="login"], a[href*="register"],
  [data-testid="link"], a.link { color: #5fd0c6 !important; }

  /* ============================================================
     404 / error page ("Ups, mamy problem")

     A completely separate, non-React template: no design tokens, no page
     shell ids, just .c-container / .c-wrapper on a literal cream #FFFBEF
     canvas. None of the theme's anchors reach it, so it shipped as a
     full-viewport cream page whose heading inherited the light body text
     colour and became unreadable. Anchor on the stable data-cy hook.
     ============================================================ */
  [data-cy="404-page"],
  [data-cy="404-page"] .c-wrapper {
    background-color: #14181d !important;
  }
  [data-cy="404-page"] .c-container__title {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  [data-cy="404-page"] .c-container__description {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }
  [data-cy="404-page"] button.button {
    background-color: #1fcabf !important;
    border-color: #1fcabf !important;
    color: #07232a !important;
    -webkit-text-fill-color: #07232a !important;
  }

  /* ============================================================
     Breadcrumbs (literal dark-teal text on the listing/offer pages)
     ============================================================ */
  [data-testid="breadcrumbs"], [data-testid="breadcrumbs"] *,
  nav[aria-label*="readcrumb"] a, [class*="breadcrumb"] a {
    color: #9aa6b0 !important;
  }
  [data-testid="breadcrumbs"] a:hover { color: #e6edf3 !important; }

  /* ============================================================
     Generic links + footer
     ============================================================ */
  a { color: #c4cdd6; }
  a:hover { color: #ffffff !important; }

  /* The current OLX footer is a hashed emotion shell with NO <footer>
     element and no "footer" class — it lives under the stable
     #footerContent id. Its link/text colour is driven by the same
     near-black #02282c -webkit-text-fill token, so a plain `color`
     override (or the old footer/[class*=footer] selectors) misses it
     entirely and every footer link renders dark-on-dark. Anchor on
     #footerContent and force BOTH color and -webkit-text-fill. */
  footer,
  [data-testid="footer"],
  [class*="footer"],
  #footerContent {
    background-color: #0d1117 !important;
    color: #9aa6b0 !important;
    border-top: 1px solid #2d333b !important;
  }
  footer a, [data-testid="footer"] a { color: #9aa6b0 !important; }
  footer a:hover { color: #e6edf3 !important; }
  #footerContent a, #footerContent a span,
  #footerContent button, #footerContent button span,
  #footerContent p, #footerContent li, #footerContent span {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }
  #footerContent a:hover, #footerContent a:hover span,
  #footerContent button:hover, #footerContent button:hover span {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  /* The partner strip at the very bottom (OLX.bg / OLX.ro / OLX.ua / OLX.pt /
     Fixly / Otodom / Otomoto / obido) is the ONLY place #footerContent holds
     <svg>s, and OLX desaturates every one of them with `filter: grayscale(1)`.
     Their marks are dark ink drawn for the light #F2F4F5 footer — Otomoto's
     navy ring and obido's unfilled (so pure-black) wordmark all but disappear
     against #0d1117. They carry explicit path fills, so neither `color:inherit`
     nor a `fill` override reaches them; invert the already-grey ink instead. */
  #footerContent a svg { filter: grayscale(1) invert(1) !important; }

  /* ============================================================
     Scrollbar polish
     ============================================================ */
  ::-webkit-scrollbar { width: 12px; height: 12px; }
  ::-webkit-scrollbar-track { background: #0d1117; }
  ::-webkit-scrollbar-thumb { background: #2d333b; border-radius: 6px; }
  ::-webkit-scrollbar-thumb:hover { background: #3a424c; }
}
